```ruby
class Cache
  def initialize(packer: nil)
    @packer = packer
    @store = {}
  end

  def write(key, payload, stale: false)
    entry = { payload: payload, stale: stale }
    @store[key] = @packer ? @packer.dump(entry) : entry
  end

  def read(key)
    return nil unless @store.key?(key)
    entry = load_entry(@store[key])
    entry[:payload]
  end

  def sweep
    keys_to_remove = []
    @store.each do |key, raw|
      entry = load_entry(raw)
      keys_to_remove << key if entry[:stale]
    end
    keys_to_remove.each { |key| @store.delete(key) }
  end

  private

  def load_entry(raw)
    @packer ? @packer.load(raw) : raw
  end
end
